import './fetchStub';
import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import App from './App';

test('renders three tabs and a single panel', () => {
  const { container } = render(<App />);
  expect(container.querySelectorAll('[role="tab"]')).toHaveLength(3);
  expect(container.querySelectorAll('[role="tabpanel"]')).toHaveLength(1);
});

test('marks only the chosen tab as selected', () => {
  const { container } = render(<App />);
  const tabs = [...container.querySelectorAll('[role="tab"]')];
  expect(tabs[0].getAttribute('aria-selected')).toBe('true');
  expect(tabs[1].getAttribute('aria-selected')).toBe('false');
  fireEvent.click(tabs[1]);
  expect(tabs[1].getAttribute('aria-selected')).toBe('true');
  expect(tabs[0].getAttribute('aria-selected')).toBe('false');
});

test('shows the panel belonging to the chosen tab', () => {
  const { container } = render(<App />);
  const panel = () => container.querySelector('[role="tabpanel"]').textContent;
  expect(panel()).toContain('Profile');
  fireEvent.click(container.querySelectorAll('[role="tab"]')[2]);
  expect(panel()).toContain('Alert');
  expect(panel()).not.toContain('Profile');
});

solution.solution:
const tabs = [
  { id: 'profile', label: 'Profile', panel: 'Profile details' },
  { id: 'billing', label: 'Billing', panel: 'Billing details' },
  { id: 'alerts', label: 'Alerts', panel: 'Alert settings' },
];

const App = () => {
  const [activeId, setActiveId] = useState(tabs[0].id);
  const active = tabs.find(tab => tab.id === activeId);
  return <><div role="tablist">{tabs.map(tab => <button key={tab.id} role="tab" aria-selected={tab.id === activeId} onClick={() => setActiveId(tab.id)}>{tab.label}</button>)}</div><div role="tabpanel">{active.panel}</div></>;
};

